package in.ultraop.mobchests.command;
import in.ultraop.mobchests.UltraOPMobChestsPlugin;import in.ultraop.mobchests.loot.CustomMobItems;import net.kyori.adventure.text.Component;import net.kyori.adventure.text.serializer.plain.PlainTextComponentSerializer;import org.bukkit.Bukkit;import org.bukkit.ChatColor;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.bukkit.event.EventHandler;import org.bukkit.event.Listener;import org.bukkit.event.inventory.InventoryClickEvent;import org.bukkit.inventory.Inventory;import org.bukkit.inventory.ItemStack;import org.jetbrains.annotations.NotNull;import org.jetbrains.annotations.Nullable;import java.util.ArrayList;import java.util.List;import java.util.Locale;
public final class MobChestsCommand implements CommandExecutor,TabCompleter,Listener {
 private static final String GUI="MobChests Custom Items";private final UltraOPMobChestsPlugin plugin;public MobChestsCommand(UltraOPMobChestsPlugin p){plugin=p;}
 @Override public boolean onCommand(@NotNull CommandSender s,@NotNull Command c,@NotNull String l,@NotNull String[] a){if(a.length==0){help(s);return true;}switch(a[0].toLowerCase(Locale.ROOT)){case "info"->info(s);case "help"->help(s);case "status"->status(s);case "reload"->reload(s);case "items"->items(s);case "give"->give(s,a);default->s.sendMessage(ChatColor.RED+"Unknown subcommand. Use /mobchest help.");}return true;}
 private void info(CommandSender s){s.sendMessage(plugin.messages().color("&6&lMOB CHESTS — ABOUT"));s.sendMessage(plugin.messages().color("&7Minecraft: &f26.3 &8| &7Server: &fPaper"));s.sendMessage(plugin.messages().color("&7Plugin: &f"+plugin.getDescription().getVersion()));s.sendMessage(plugin.messages().color("&7Custom weapons: &a"+CustomMobItems.all().size()));}
 private void help(CommandSender s){plugin.messages().sendLines(s,"help.lines");s.sendMessage(ChatColor.GOLD+"/mobchest items"+ChatColor.GRAY+" - Browse custom weapons");if(s.hasPermission("mobchests.admin"))s.sendMessage(ChatColor.GOLD+"/mobchest give <player> <item>"+ChatColor.GRAY+" - Give custom weapon");}
 private void status(CommandSender s){s.sendMessage(plugin.messages().color("&6&lMOB CHESTS STATUS"));s.sendMessage(plugin.messages().color("&7Plugin: &aEnabled"));s.sendMessage(plugin.messages().color("&7Mob support: &a"+plugin.settings().supportedMobTypeCount()+" / "+plugin.settings().totalMobTypeCount()));s.sendMessage(plugin.messages().color("&7Custom weapons: &a"+CustomMobItems.all().size()));}
 private void reload(CommandSender s){if(!s.hasPermission("mobchests.admin")){s.sendMessage(ChatColor.RED+"You do not have permission.");return;}plugin.reloadPluginData();s.sendMessage(plugin.messages().color("&aConfiguration reloaded."));}
 private void items(CommandSender s){if(!(s instanceof Player p)){s.sendMessage("Only players can open the item browser.");return;}Inventory inv=Bukkit.createInventory(null,27,Component.text(GUI));int[] slots={10,12,14,16,22};for(int i=0;i<CustomMobItems.all().size();i++)inv.setItem(slots[i],CustomMobItems.create(CustomMobItems.all().get(i)));p.openInventory(inv);}
 private void give(CommandSender s,String[] a){if(!s.hasPermission("mobchests.admin")){s.sendMessage(ChatColor.RED+"You do not have permission.");return;}if(a.length<3){s.sendMessage(ChatColor.YELLOW+"Usage: /mobchest give <player> <item>");return;}Player p=Bukkit.getPlayerExact(a[1]);if(p==null){s.sendMessage(ChatColor.RED+"Player is not online.");return;}CustomMobItems.Definition d=CustomMobItems.byName(String.join(" ",java.util.Arrays.copyOfRange(a,2,a.length)));if(d==null){s.sendMessage(ChatColor.RED+"Unknown item. Use /mobchest items.");return;}p.getInventory().addItem(CustomMobItems.create(d));s.sendMessage(ChatColor.GREEN+"Gave "+d.name()+" to "+p.getName()+".");}
 @EventHandler public void click(InventoryClickEvent e){if(!PlainTextComponentSerializer.plainText().serialize(e.getView().title()).equals(GUI))return;e.setCancelled(true);if(e.getRawSlot()<0||e.getRawSlot()>=e.getView().getTopInventory().getSize())return;ItemStack i=e.getCurrentItem();if(i==null||!i.hasItemMeta()||i.getItemMeta().displayName()==null)return;String n=PlainTextComponentSerializer.plainText().serialize(i.getItemMeta().displayName());CustomMobItems.Definition d=CustomMobItems.byName(n);if(d!=null&&e.getWhoClicked() instanceof Player p){p.getInventory().addItem(CustomMobItems.create(d));p.sendMessage(ChatColor.GREEN+"Received "+d.name()+".");}}
 @Override public @Nullable List<String> onTabComplete(@NotNull CommandSender s,@NotNull Command c,@NotNull String l,@NotNull String[] a){if(a.length==1){List<String> o=new ArrayList<>(List.of("info","help","status","items"));if(s.hasPermission("mobchests.admin")){o.add("reload");o.add("give");}return o.stream().filter(x->x.startsWith(a[0].toLowerCase(Locale.ROOT))).toList();}if(a.length==2&&a[0].equalsIgnoreCase("give")&&s.hasPermission("mobchests.admin"))return Bukkit.getOnlinePlayers().stream().map(Player::getName).filter(x->x.toLowerCase(Locale.ROOT).startsWith(a[1].toLowerCase(Locale.ROOT))).toList();if(a.length>=3&&a[0].equalsIgnoreCase("give")&&s.hasPermission("mobchests.admin")){String p=a[a.length-1].toLowerCase(Locale.ROOT);return CustomMobItems.all().stream().map(CustomMobItems.Definition::name).filter(x->x.toLowerCase(Locale.ROOT).startsWith(p)).toList();}return List.of();}
}